/**
 * `checkLimit` arithmetic and downgrade refusal.
 *
 * Owner C implements `@/server/services/billing-service`.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as billingService from "@/server/services/billing-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("services/billing-service", () => {
  // checkLimit reads the ceiling from getPlanLimits(), never a hard-coded number.
  it("computes remaining and exceeded from the plan's quota", async () => {
    const tenant = await createTenant("billing-remaining", "starter");
    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 4 });

    const check = await billingService.checkLimit(tenant.org.id, "seats", 1);

    expect(check.plan).toBe("starter");
    expect(check.limit).toBe(10);
    expect(check.used).toBe(4);
    expect(check.remaining).toBe(6);
    expect(check.exceeded).toBe(false);
  });

  // At exactly the quota the resource is exceeded and remaining is zero.
  it("marks a resource exceeded at, not past, the quota", async () => {
    const tenant = await createTenant("billing-exact", "starter");
    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 10 });

    const check = await billingService.checkLimit(tenant.org.id, "seats");

    expect(check.limit).toBe(10);
    expect(check.used).toBe(10);
    expect(check.remaining).toBe(0);
    expect(check.exceeded).toBe(true);
  });

  // An unlimited enterprise quota is never exceeded and reports Infinity remaining.
  it("never marks an unlimited quota exceeded", async () => {
    const tenant = await createTenant("billing-unlimited", "enterprise");
    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 1_000_000 });

    const check = await billingService.checkLimit(tenant.org.id, "seats", 500);

    expect(check.limit).toBe(Number.POSITIVE_INFINITY);
    expect(check.exceeded).toBe(false);
    expect(check.remaining).toBe(Number.POSITIVE_INFINITY);
  });

  // A downgrade whose current usage breaches the target plan is refused.
  it("refuses a downgrade that current usage would breach", async () => {
    const tenant = await createTenant("billing-downgrade", "growth");
    await usageRepo.incrementUsage(tenant.org.id, { seatsUsed: 5 });

    await expect(
      billingService.changePlan(tenant.actors.owner, {
        orgId: tenant.org.id,
        plan: "free",
        interval: "monthly",
      }),
    ).rejects.toThrow(/seats exceeds its limit/);
  });

  // billing.plan_changed carries the previous and new plan.
  it("emits billing.plan_changed on a successful plan change", async () => {
    const tenant = await createTenant("billing-plan-changed", "growth");

    let off: Unsubscribe | undefined;
    const received = await new Promise((resolve) => {
      off = subscribe("billing.plan_changed", (payload) => {
        resolve(payload);
      });
      void billingService.changePlan(tenant.actors.owner, {
        orgId: tenant.org.id,
        plan: "enterprise",
        interval: "monthly",
      });
    });
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      from: "growth",
      to: "enterprise",
    });
  });

  // Crossing a ceiling emits billing.limit_exceeded with resource, limit and used.
  it("emits billing.limit_exceeded when a ceiling is crossed", async () => {
    const tenant = await createTenant("billing-limit-exceeded", "starter");
    await usageRepo.incrementUsage(tenant.org.id, { projectsUsed: 10 });

    let off: Unsubscribe | undefined;
    const receivedPromise = new Promise((resolve) => {
      off = subscribe("billing.limit_exceeded", (payload) => {
        resolve(payload);
      });
    });

    await expect(
      billingService.assertWithinLimit(tenant.org.id, "projects", 1),
    ).rejects.toThrow(/allows 10 projects/);

    const received = await receivedPromise;
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      resource: "projects",
      limit: 10,
      used: 10,
    });
  });

  // can(actor, "org:manage_billing", …) — only an owner may change the plan.
  it("refuses a plan change to anyone but an owner", async () => {
    const tenant = await createTenant("billing-owner-only", "growth");

    await expect(
      billingService.changePlan(tenant.actors.admin, {
        orgId: tenant.org.id,
        plan: "enterprise",
        interval: "monthly",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });
});
/**
 * The background job layer: the in-process queue, the scheduler's cadence and
 * the two jobs whose behaviour other layers depend on — the overdue scan that
 * feeds the notification fan-out, and the trial expiry that moves plans.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import {
  drain,
  enqueue,
  isSchedulerRunning,
  pendingCount,
  resetQueue,
  startScheduler,
  stopScheduler,
} from "@/server/jobs";
import { backoffMs } from "@/server/jobs/webhook-delivery-job";
import { shouldRunForOrg } from "@/server/jobs/digest-email-job";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

const PAST = "2026-01-01T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("jobs");
  await usageRepo.recomputeUsage(tenant.org.id);
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  resetQueue();
  stopScheduler();
});

afterAll(() => {
  cleanup();
});

describe("the in-process queue", () => {
  it("is idempotent on the job id", () => {
    const job = {
      id: "usage-rollup:1",
      kind: "usage-rollup" as const,
      runAt: toIsoTimestamp(NOW),
      attempts: 0,
      payload: {},
    };

    enqueue(job);
    enqueue(job);

    expect(pendingCount()).toBe(1);
  });

  it("leaves jobs scheduled in the future alone", async () => {
    enqueue({
      id: "usage-rollup:future",
      kind: "usage-rollup",
      runAt: toIsoTimestamp(new Date(Date.now() + 3_600_000)),
      attempts: 0,
      payload: {},
    });

    await expect(drain()).resolves.toBe(0);
    expect(pendingCount()).toBe(1);
  });

  it("runs a due job and removes it", async () => {
    enqueue({
      id: "usage-rollup:due",
      kind: "usage-rollup",
      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
      attempts: 0,
      payload: {},
    });

    await expect(drain()).resolves.toBe(1);
    expect(pendingCount()).toBe(0);
  });
});

describe("the scheduler", () => {
  it("reports whether it is running and stops cleanly", () => {
    expect(isSchedulerRunning()).toBe(false);
    startScheduler();
    expect(isSchedulerRunning()).toBe(true);
    stopScheduler();
    expect(isSchedulerRunning()).toBe(false);
  });
});

describe("the overdue scan", () => {
  it("emits issue.overdue for a past-due open issue, once", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late already",
        assigneeId: tenant.userIds.member,
        dueAt: PAST,
      }),
    );

    const seen: string[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push(payload.issueId);
      }),
    );

    const result = await runOverdueIssueJob(NOW);

    expect(seen).toEqual([issue.id]);
    expect(result.kind).toBe("overdue-issues");
    expect(result.processed).toBe(1);
    expect(result.failed).toBe(0);
  });

  it("ignores an overdue issue once it is archived", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late but archived",
        dueAt: PAST,
      }),
    );
    await issueService.archiveIssue(
      tenant.actors.member,
      tenant.org.id,
      issue.id,
    );

    const overdue = await issueRepo.listOverdueIssues(
      tenant.org.id,
      toIsoTimestamp(NOW),
    );

    expect(overdue.map((row) => row.id)).not.toContain(issue.id);
  });

  it("ignores an overdue issue once it is closed", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late but done",
        dueAt: PAST,
      }),
    );
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "done",
    });

    const overdue = await issueRepo.listOverdueIssues(
      tenant.org.id,
      toIsoTimestamp(NOW),
    );

    expect(overdue.map((row) => row.id)).not.toContain(issue.id);
  });
});

describe("the usage rollup", () => {
  it("recounts the tenant's live rows", async () => {
    const result = await runUsageRollupJob(NOW);
    expect(result.processed).toBeGreaterThan(0);

    const usage = await usageRepo.getUsage(tenant.org.id);
    const live = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
    });

    expect(usage.issuesUsed).toBe(live.total);
    expect(usage.seatsUsed).toBe(4);
  });
});

describe("pure job helpers", () => {
  it("backs delivery attempts off exponentially, with a ceiling", () => {
    expect(backoffMs(0)).toBe(0);
    expect(backoffMs(1)).toBe(1_000);
    expect(backoffMs(2)).toBe(2_000);
    expect(backoffMs(3)).toBe(4_000);
    expect(backoffMs(30)).toBe(300_000);
  });

  it("runs the digest only during the org's configured UTC hour", () => {
    const org = {
      ...tenant.org,
      settings: { ...tenant.org.settings, digestHourUtc: 7 },
    };

    expect(shouldRunForOrg(org, NOW)).toBe(true);
    expect(
      shouldRunForOrg(org, new Date("2026-06-01T08:00:00.000Z")),
    ).toBe(false);
    expect(
      shouldRunForOrg({ ...org, archivedAt: toIsoTimestamp(NOW) }, NOW),
    ).toBe(false);
  });
});
import type {
  ActivityId,
  IsoTimestamp,
  ProjectId,
  TenantScoped,
  UserId,
} from "./common";

/** The verb recorded in the audit log. Kept deliberately close to the event
 *  bus keys so `ActivityService` can map one to the other mechanically. */
export type ActivityAction =
  | "organization.updated"
  | "project.created"
  | "project.updated"
  | "project.archived"
  | "project.restored"
  | "issue.created"
  | "issue.updated"
  | "issue.status_changed"
  | "issue.assigned"
  | "issue.archived"
  | "issue.restored"
  | "comment.created"
  | "comment.updated"
  | "comment.deleted"
  | "member.invited"
  | "member.joined"
  | "member.role_changed"
  | "member.removed"
  | "billing.plan_changed"
  | "flag.toggled";

export type ActivitySubjectKind =
  | "organization"
  | "project"
  | "issue"
  | "comment"
  | "member"
  | "subscription"
  | "feature_flag";

export interface ActivityEvent extends TenantScoped {
  readonly id: ActivityId;
  readonly action: ActivityAction;
  readonly actorId: UserId | null;
  readonly subjectKind: ActivitySubjectKind;
  readonly subjectId: string;
  readonly projectId: ProjectId | null;
  readonly summary: string;
  readonly metadata: Readonly<Record<string, string | number | boolean | null>>;
  readonly occurredAt: IsoTimestamp;
}

/** Filter for the activity feed page and the audit-log CSV export. */
export interface ActivityFilter {
  readonly action?: readonly ActivityAction[];
  readonly actorId?: UserId;
  readonly projectId?: ProjectId;
  readonly subjectKind?: ActivitySubjectKind;
  readonly since?: IsoTimestamp;
  readonly until?: IsoTimestamp;
}

/** Activity rows grouped by calendar day, as the feed renders them. */
export interface ActivityGroup {
  readonly day: string;
  readonly events: readonly ActivityEvent[];
}
import { z } from "zod";
import {
  isoTimestampSchema,
  orgIdSchema,
  pageRequestSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";

export const activityActionSchema = z.enum([
  "organization.updated",
  "project.created",
  "project.updated",
  "project.archived",
  "project.restored",
  "issue.created",
  "issue.updated",
  "issue.status_changed",
  "issue.assigned",
  "issue.archived",
  "issue.restored",
  "comment.created",
  "comment.updated",
  "comment.deleted",
  "member.invited",
  "member.joined",
  "member.role_changed",
  "member.removed",
  "billing.plan_changed",
  "flag.toggled",
]);

export const activitySubjectKindSchema = z.enum([
  "organization",
  "project",
  "issue",
  "comment",
  "member",
  "subscription",
  "feature_flag",
]);

export const activityFilterSchema = z
  .object({
    orgId: orgIdSchema,
    action: z.array(activityActionSchema).optional(),
    actorId: userIdSchema.optional(),
    projectId: projectIdSchema.optional(),
    subjectKind: activitySubjectKindSchema.optional(),
    since: isoTimestampSchema.optional(),
    until: isoTimestampSchema.optional(),
  })
  .extend(pageRequestSchema.shape);

export const exportActivitySchema = z.object({
  orgId: orgIdSchema,
  since: isoTimestampSchema,
  until: isoTimestampSchema,
  format: z.enum(["csv", "json"]).default("csv"),
});

export type ActivityFilterInput = z.infer<typeof activityFilterSchema>;
export type ExportActivityInput = z.infer<typeof exportActivitySchema>;
import type {
  CommentId,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
  UserId,
  IsoTimestamp,
} from "./common";
import type { IssueStatus, IssuePriority } from "./issue";
import type { Role } from "./member";
import type { PlanId, LimitedResource } from "./billing";
import type { FeatureFlagKey } from "./feature-flag";

/** Fields present on every event payload; the bus stamps them on `emit`. */
export interface EventEnvelope {
  readonly orgId: OrgId;
  readonly actorId: UserId | null;
  readonly occurredAt: IsoTimestamp;
}

/**
 * The complete catalogue of domain events. `emit()` and `subscribe()` in
 * `src/lib/event-bus.ts` are keyed on this map, so adding an event here is the
 * only way to introduce one — services, jobs and the webhook dispatcher all
 * derive their handler signatures from it.
 */
export interface TaskflowEventMap {
  "project.created": EventEnvelope & {
    projectId: ProjectId;
    name: string;
    slug: string;
  };
  "project.archived": EventEnvelope & {
    projectId: ProjectId;
    issuesArchived: number;
  };
  "project.restored": EventEnvelope & { projectId: ProjectId };
  "issue.created": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    title: string;
    assigneeId: UserId | null;
    priority: IssuePriority;
  };
  "issue.updated": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    changedFields: readonly string[];
  };
  "issue.status_changed": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    from: IssueStatus;
    to: IssueStatus;
  };
  "issue.assigned": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    previousAssigneeId: UserId | null;
    assigneeId: UserId;
  };
  "issue.archived": EventEnvelope & { issueId: IssueId; projectId: ProjectId };
  "issue.overdue": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    dueAt: IsoTimestamp;
    assigneeId: UserId | null;
  };
  "comment.created": EventEnvelope & {
    commentId: CommentId;
    issueId: IssueId;
    mentionedUserIds: readonly UserId[];
  };
  "comment.deleted": EventEnvelope & { commentId: CommentId; issueId: IssueId };
  "member.invited": EventEnvelope & { email: string; role: Role };
  "member.joined": EventEnvelope & { memberId: MemberId; userId: UserId; role: Role };
  "member.role_changed": EventEnvelope & {
    memberId: MemberId;
    from: Role;
    to: Role;
  };
  "member.removed": EventEnvelope & { memberId: MemberId; userId: UserId };
  "billing.plan_changed": EventEnvelope & { from: PlanId; to: PlanId };
  "billing.limit_exceeded": EventEnvelope & {
    resource: LimitedResource;
    limit: number;
    used: number;
  };
  "flag.toggled": EventEnvelope & { flag: FeatureFlagKey; enabled: boolean };
  "digest.due": EventEnvelope & { recipientId: UserId; windowStart: IsoTimestamp };
  "search.reindex_requested": EventEnvelope & {
    subjectKind: "issue" | "comment" | "project";
    subjectId: string;
  };
  "webhook.delivery_requested": EventEnvelope & {
    eventType: string;
    payload: Readonly<Record<string, unknown>>;
  };
}

export type TaskflowEventType = keyof TaskflowEventMap;

export type TaskflowEventPayload<K extends TaskflowEventType> =
  TaskflowEventMap[K];

/** A handler registered with `subscribe()`. May be async; errors are isolated. */
export type EventHandler<K extends TaskflowEventType> = (
  payload: TaskflowEventPayload<K>,
) => void | Promise<void>;

/** Returned by `subscribe()`; calling it removes the handler. */
export type Unsubscribe = () => void;

