/** Feeds the billing-renewal job; cross-tenant by design, it sweeps every org. */
export async function listAllSubscriptions(): Promise<readonly Subscription[]> {
  const rows = getDb().select().from(subscriptions).all();
  return rows.map(toSubscription);
