/**
 * Rewrites the billing state of a subscription: plan, interval, status, the
 * current period and any pending cancellation. Used by renewals, cancellation
 * hand-over and mid-period plan changes that start a fresh period.
 */
export async function updateSubscriptionBilling(
  orgId: OrgId,
  patch: {
    plan?: PlanId;
    interval?: BillingInterval;
    status?: Subscription["status"];
    currentPeriodStart?: IsoTimestamp;
    currentPeriodEnd?: IsoTimestamp;
    cancelAt?: IsoTimestamp | null;
  },
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({ ...patch, updatedAt: toIsoTimestamp(new Date()) })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}
