/** The full charge for one period of `plan` at `seats`, in cents. */
export function fullPeriodChargeCents(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return getPlanLimits(plan).priceCentsPerSeatMonthly * seats * monthsIn(interval);
